      previews.after(el(section('Uma visão mais próxima','Veja o estudo ganhar forma na tela.','Prévias ilustrativas baseadas na organização e nas funcionalidades do Caderno de Gastronomia. Aqui, as telas apresentam exemplos de uso para você conhecer cada área.',`<div class="screens-grid">${screens.map((s,i)=>`<article class="preview-explained"><div class="screen-frame tone-${i%6}">${mark(s[0],s[3])}</div><span class="more-kicker">${s[0]}</span><h3>${s[1]}</h3><p>${s[2]}</p></article>`).join('')}</div>`,'screen-section')));
